<?php
require_once __DIR__.'/includes/auth.php'; require_once __DIR__.'/includes/appconfig.php'; require_once __DIR__.'/includes/icons.php'; require_once __DIR__.'/includes/permissions.php'; require_once __DIR__.'/includes/reporting.php';
auth_require(); permissions_require_menu('reportes'); report_ensure_tables();
$APP_USER=auth_user();$APP_ROLE='Administrador';$ACTIVE='reportes';
$db=clear_db();$requestedScreen=trim((string)($_GET['pantalla']??''));$catalogForRequest=report_screen_catalog();if($requestedScreen!==''&&!isset($catalogForRequest[$requestedScreen]))$requestedScreen='';$rows=$db->all("SELECT * FROM dbo.CLEAR_REPORT_SCHEDULES ORDER BY ACTIVO DESC,NOMBRE");$logs=$db->all("SELECT TOP 30 L.*,S.NOMBRE FROM dbo.CLEAR_REPORT_LOG L LEFT JOIN dbo.CLEAR_REPORT_SCHEDULES S ON S.ID=L.ID_REPORTE ORDER BY L.FECHA_EJECUCION DESC");$schedulerLast=report_setting('SCHEDULER_LAST_RUN','');$schedulerTs=$schedulerLast!==''?strtotime($schedulerLast):false;$schedulerOk=$schedulerTs!==false&&(time()-$schedulerTs)<=300;
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reportes por correo</title><link rel="stylesheet" href="assets/css/app.css?v=20260715-1"><style>
.reportGrid{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(390px,.75fr);gap:20px}.panel{background:#fff;border:1px solid var(--line-mid);border-top:3px solid var(--petrol);border-radius:14px;padding:18px}.panel h2{font-family:var(--font-head);font-size:20px;margin:0 0 14px}.fgrid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.fgrid .full{grid-column:1/-1}.field label{display:block;font-size:12px;font-weight:700;color:var(--text-soft);margin-bottom:5px}.field input,.field select,.field textarea{width:100%;padding:10px;border:1px solid var(--line-mid);border-radius:9px;font:inherit}.field textarea{min-height:80px}.days{display:flex;gap:7px;flex-wrap:wrap}.days label{border:1px solid var(--line-mid);padding:7px 9px;border-radius:8px;background:#f8fbfc}
.reportScreens{display:flex;flex-direction:column;flex-wrap:nowrap;gap:0;max-height:500px;overflow:auto;padding:0;border:1px solid var(--line-mid);border-radius:10px;background:#fff}
.reportScreens label{display:grid;grid-template-columns:24px minmax(0,1fr);align-items:center;column-gap:10px;min-height:52px;padding:8px 11px;margin:0;border:0;border-bottom:1px solid var(--line);border-radius:0;background:#fff;cursor:pointer}
.reportScreens label:last-child{border-bottom:0}.reportScreens label:hover{background:var(--petrol-soft)}.reportScreens label:has(input:checked){background:#f0f8fa;box-shadow:inset 3px 0 0 var(--petrol)}
.reportScreens input[type=checkbox]{width:16px;height:16px;margin:0;justify-self:center}
.reportScreenMeta{display:flex;flex-direction:column;min-width:0;gap:2px}
.reportScreenName{display:block;min-width:0;color:var(--text);font-size:12.5px;font-weight:750;line-height:1.25;white-space:normal;overflow-wrap:anywhere}
.reportScreenGroup{display:block;color:var(--text-mut);font-size:10px;line-height:1.2;text-align:left;white-space:normal;overflow-wrap:anywhere}
.reportTemplates{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px}.reportTemplate{border:1px solid var(--line-mid);background:#f7fbfc;padding:9px 11px;border-radius:9px;cursor:pointer;font-weight:700;color:var(--petrol)}.reportScreenTools{display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:8px;align-items:center;margin-bottom:8px}.reportScreenTools input{min-width:0}.reportScreenTools button{white-space:nowrap}
@media(max-width:700px){.reportScreenTools{grid-template-columns:1fr 1fr}.reportScreenTools input{grid-column:1/-1}.reportScreenGroup{display:block}}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}.btn{border:1px solid var(--line-mid);background:#fff;padding:9px 13px;border-radius:9px;cursor:pointer}.btn.primary{background:var(--petrol);color:#fff;border-color:var(--petrol)}.btn.danger{color:#b42318}.sched{display:grid;gap:10px}.schedItem{border:1px solid var(--line);border-radius:11px;padding:12px}.schedTop{display:flex;justify-content:space-between;gap:10px}.badge{font-size:11px;border-radius:20px;padding:4px 8px;background:var(--green-soft);color:var(--green-tx)}.badge.off{background:#eef2f5;color:#607080}.muted{color:var(--text-mut);font-size:12px}.logTable{width:100%;border-collapse:collapse;font-size:12px}.logTable th,.logTable td{padding:8px;border-bottom:1px solid var(--line);text-align:left}@media(max-width:1000px){.reportGrid{grid-template-columns:1fr}}
</style></head><body><div class="app"><?php include __DIR__.'/includes/sidebar.php';?><main class="main"><?php include __DIR__.'/includes/topbar.php';?><div class="page__head"><div><h1 class="page__title">Reportes por correo</h1><div class="page__sub">PDF automático de las pantallas seleccionadas y programación de envíos</div></div><div class="page__live"><span class="dot"></span>Administración</div></div>
<div id="msg"></div><div class="reportGrid"><section class="panel"><h2>Programaciones</h2><div class="sched"><?php if(!$rows):?><div class="muted">Todavía no hay reportes programados.</div><?php endif;foreach($rows as $r):?><div class="schedItem"><div class="schedTop"><div><b><?=h($r['NOMBRE'])?></b><div class="muted">Propietario: <b><?=h($r['USUARIO_CARGA']?:'Sin asignar')?></b></div><div class="muted"><?=h($r['DESTINATARIOS'])?> · <?=h($r['FRECUENCIA'])?> · <?=h($r['HORARIOS'])?></div><div class="muted">Pantallas: <?=h(implode(', ',array_map(function($k){$c=report_screen_catalog();return $c[$k]??$k;},report_parse_screens($r['PANTALLAS']??$r['TIPO_REPORTE']??'dashboard'))))?></div><div class="muted">Próximo: <?=h($r['PROXIMA_EJECUCION']?:'Pendiente de calcular')?> · Último: <?=h($r['ULTIMO_ESTADO']?:'Sin envíos')?></div></div><span class="badge <?=$r['ACTIVO']?'':'off'?>"><?=$r['ACTIVO']?'Activo':'Pausado'?></span></div><div class="actions"><button class="btn" onclick='editSchedule(<?=json_encode($r,JSON_HEX_APOS|JSON_HEX_QUOT)?>)'>Editar</button><button class="btn" onclick="sendNow(<?=$r['ID']?>)">Enviar prueba</button><button class="btn danger" onclick="removeSchedule(<?=$r['ID']?>)">Eliminar</button></div></div><?php endforeach;?></div>
<h2 style="margin-top:24px">Historial reciente</h2><div style="overflow:auto"><table class="logTable"><thead><tr><th>Fecha</th><th>Reporte</th><th>Estado</th><th>Destinatarios</th><th>Error</th></tr></thead><tbody><?php foreach($logs as $l):?><tr><td><?=h($l['FECHA_EJECUCION'])?></td><td><?=h($l['NOMBRE']?:'-')?></td><td><?=h($l['ESTADO'])?></td><td><?=h($l['DESTINATARIOS'])?></td><td><?=h($l['ERROR'])?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="panel"><h2 id="formTitle">Nuevo reporte</h2><div class="reportTemplates"><button type="button" class="reportTemplate" data-template="operativo">Plantilla operativa diaria</button><button type="button" class="reportTemplate" data-template="pozos">Plantilla de pozos</button><button type="button" class="reportTemplate" data-template="gestion">Plantilla de gestión</button><button type="button" class="reportTemplate" data-template="ia">Diagnóstico IA</button></div><form id="scheduleForm"><input type="hidden" name="id" id="sid"><input type="hidden" name="action" value="save_schedule"><div class="fgrid"><div class="field full"><label>Nombre</label><input required name="nombre" id="nombre"></div><div class="field full"><label>Destinatarios</label><input required name="destinatarios" id="destinatarios" placeholder="correo1@empresa.com; correo2@empresa.com"></div><div class="field"><label>CC</label><input name="cc" id="cc"></div><div class="field"><label>CCO</label><input name="cco" id="cco"></div><div class="field full"><label>Asunto</label><input required name="asunto" id="asunto" value="CLEAR Petroleum | Reporte operativo de alarmas"></div><div class="field full"><label>Cuerpo del correo</label><textarea name="cuerpo" id="cuerpo">Se adjuntan los reportes operativos automáticos de CLEAR Petroleum.</textarea></div><div class="field full"><label>Pantallas incluidas en PDF</label><div class="reportScreenTools"><input type="search" id="reportScreenSearch" placeholder="Buscar pantalla…"><button type="button" class="btn" id="selectAllScreens">Marcar todas</button><button type="button" class="btn" id="clearAllScreens">Desmarcar</button></div><div class="days reportScreens"><?php foreach(report_screen_picker_definitions() as $screenKey=>$screenDef):$screenLabel=(string)($screenDef['label']??$screenKey);$screenGroup=(string)($screenDef['group']??'Otros');?><label data-screen-label="<?=h(strtolower($screenLabel.' '.$screenGroup))?>"><input type="checkbox" name="pantallas[]" value="<?=h($screenKey)?>" <?=($requestedScreen!==''?$screenKey===$requestedScreen:$screenKey==='dashboard_inst_sup')?'checked':''?>><span class="reportScreenMeta"><span class="reportScreenName"><?=h($screenLabel)?></span><small class="reportScreenGroup"><?=h($screenGroup)?></small></span></label><?php endforeach;?></div><div class="muted" style="margin-top:6px"><?=count(report_screen_picker_definitions())?> pantallas disponibles. Se incluyen las pantallas operativas del menú de CLEAR y las vistas específicas de reportes.</div></div><div class="field"><label>Frecuencia</label><select name="frecuencia" id="frecuencia"><option value="daily">Diario</option><option value="weekdays">Lunes a viernes</option><option value="weekly">Semanal</option><option value="custom">Días seleccionados</option><option value="monthly">Primer día del mes</option></select></div><div class="field"><label>Horarios</label><input required name="horarios" id="horarios" value="08:00" placeholder="08:00,20:00"></div><div class="field full"><label>Días de semana</label><div class="days"><?php foreach([1=>'Lun',2=>'Mar',3=>'Mié',4=>'Jue',5=>'Vie',6=>'Sáb',7=>'Dom'] as $n=>$d):?><label><input type="checkbox" name="dias[]" value="<?=$n?>"> <?=$d?></label><?php endforeach;?></div></div><div class="field"><label>Zona horaria</label><input name="zona_horaria" id="zona_horaria" value="America/Argentina/Buenos_Aires"></div><div class="field"><label>Estado</label><select name="activo" id="activo"><option value="1">Activo</option><option value="0">Pausado</option></select></div></div><div class="actions"><button class="btn primary" type="submit">Guardar programación</button><button class="btn" type="button" onclick="resetForm()">Limpiar</button></div></form>
<hr style="border:0;border-top:1px solid var(--line);margin:22px 0"><h2>Configuración SMTP y PDF</h2><form id="settingsForm"><input type="hidden" name="action" value="save_settings"><div class="fgrid"><div class="field full"><label>URL pública/interna de la aplicación</label><input name="APP_BASE_URL" value="<?=h(report_setting('APP_BASE_URL','http://localhost/CLEAR'))?>"></div><div class="field full"><label>Ruta de Google Chrome</label><input name="CHROME_PATH" value="<?=h(report_setting('CHROME_PATH','C:\Program Files\Google\Chrome\Application\chrome.exe'))?>"></div><div class="field"><label>Servidor SMTP</label><input name="SMTP_HOST" value="<?=h(report_setting('SMTP_HOST'))?>"></div><div class="field"><label>Puerto</label><input name="SMTP_PORT" value="<?=h(report_setting('SMTP_PORT','587'))?>"></div><div class="field"><label>Seguridad</label><select name="SMTP_SECURE"><option value="tls" <?=report_setting('SMTP_SECURE','tls')==='tls'?'selected':''?>>STARTTLS</option><option value="ssl" <?=report_setting('SMTP_SECURE')==='ssl'?'selected':''?>>SSL</option><option value="none">Sin cifrado</option></select></div><div class="field"><label>Usuario SMTP</label><input name="SMTP_USER" value="<?=h(report_setting('SMTP_USER'))?>"></div><div class="field"><label>Contraseña SMTP</label><input type="password" name="SMTP_PASS" value="<?=h(report_setting('SMTP_PASS'))?>"></div><div class="field"><label>Correo remitente</label><input name="SMTP_FROM" value="<?=h(report_setting('SMTP_FROM'))?>"></div><div class="field full"><label>Nombre remitente</label><input name="SMTP_FROM_NAME" value="<?=h(report_setting('SMTP_FROM_NAME','CLEAR Petroleum'))?>"></div></div><div class="actions"><button class="btn primary">Guardar configuración</button></div></form></section></div></main></div>
<script>

const requestedScreen=<?=json_encode($requestedScreen,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;
if(requestedScreen==='sin_telemetria_zafiro'){
  document.addEventListener('DOMContentLoaded',function(){
    var n=document.getElementById('nombre'),a=document.getElementById('asunto'),b=document.getElementById('cuerpo');
    if(n&&!n.value)n.value='Sin telemetría en Zafiro';
    if(a)a.value='CLEAR Petroleum | Sin telemetría en Zafiro';
    if(b)b.value='Se adjunta el estado completo de pozos sin telemetría en Zafiro, con evolución semanal y producción asociada.';
  });
}
document.addEventListener('DOMContentLoaded',function(){
  if(!requestedScreen)return;
  var reportScreenSelected=document.querySelector('.reportScreens input[value="'+CSS.escape(requestedScreen)+'"]');
  if(reportScreenSelected&&reportScreenSelected.closest('label'))reportScreenSelected.closest('label').scrollIntoView({block:'center'});
});

const screenSearch=document.getElementById('reportScreenSearch');
if(screenSearch){screenSearch.addEventListener('input',function(){var q=this.value.trim().toLowerCase();document.querySelectorAll('.reportScreens label').forEach(function(l){l.style.display=!q||String(l.dataset.screenLabel||'').includes(q)?'grid':'none';});});}
document.getElementById('selectAllScreens')?.addEventListener('click',function(){document.querySelectorAll('.reportScreens input[type=checkbox]').forEach(function(x){if(x.closest('label').style.display!=='none')x.checked=true;});});
document.getElementById('clearAllScreens')?.addEventListener('click',function(){document.querySelectorAll('.reportScreens input[type=checkbox]').forEach(function(x){if(x.closest('label').style.display!=='none')x.checked=false;});});


const schedulerStatus={ok:<?=json_encode($schedulerOk)?>,last:<?=json_encode($schedulerLast?:'nunca registrada')?>};
const reportGrid=document.querySelector('.reportGrid');
if(reportGrid){const notice=document.createElement('div');notice.className='nsNotice '+(schedulerStatus.ok?'is-success':'is-warning');notice.style.marginBottom='14px';notice.innerHTML='<b>Ejecutor automático:</b> '+(schedulerStatus.ok?'Activo':'Sin actividad reciente')+' · Última comprobación: '+schedulerStatus.last+(schedulerStatus.ok?'':'. Los envíos manuales pueden funcionar aunque la tarea automática de Windows esté detenida.');reportGrid.parentNode.insertBefore(notice,reportGrid);}
const templatesBar=document.querySelector('.reportTemplates');
if(templatesBar){const button=document.createElement('button');button.type='button';button.className='reportTemplate';button.dataset.template='comentarios';button.textContent='Comentarios semanales';templatesBar.insertBefore(button,templatesBar.lastElementChild);}
const reportTemplates={
 operativo:{name:'Reporte diario de operación',screens:['dashboard_inst_sup','alarmas24h','top20_24h','reconocimientos'],subject:'CLEAR Petroleum | Reporte diario de operación',body:'Se adjunta el reporte diario de operación y seguimiento de alarmas de CLEAR Petroleum.'},
 pozos:{name:'Reporte diario de pozos',screens:['dashboard_pozos','pozos_alarmas24','top_pozos','pozos_top20'],subject:'CLEAR Petroleum | Reporte de pozos',body:'Se adjuntan los indicadores, alarmas y rankings operativos de pozos.'},
 gestion:{name:'Reporte semanal de gestión',screens:['dashboard_inst_sup','instalaciones_alarmas_semanal','top20_all','analisis_ia'],subject:'CLEAR Petroleum | Reporte semanal de gestión',body:'Se adjunta el resumen ejecutivo semanal de alarmas, tendencias y diagnóstico automático.'},
 comentarios:{name:'Comentarios de la última semana',screens:['comentarios_semana'],subject:'CLEAR Petroleum | Comentarios de la última semana',body:'Se adjunta el reporte consolidado de comentarios registrados durante los últimos 7 días.'},
 ia:{name:'Diagnóstico diario de alarmas',screens:['analisis_ia'],subject:'CLEAR Petroleum | Diagnóstico IA de alarmas',body:'Se adjunta el diagnóstico automático de alarmas correspondiente a la última semana.'}
};
document.querySelectorAll('[data-template]').forEach(function(btn){btn.addEventListener('click',function(){var t=reportTemplates[this.dataset.template];if(!t)return;nombre.value=t.name;asunto.value=t.subject;cuerpo.value=t.body;document.querySelectorAll('[name="pantallas[]"]').forEach(function(x){x.checked=t.screens.includes(x.value);});if(this.dataset.template==='gestion'||this.dataset.template==='comentarios'){frecuencia.value='weekly';}else{frecuencia.value='daily';}window.scrollTo({top:document.getElementById('scheduleForm').offsetTop-20,behavior:'smooth'});});});

function post(fd){
  return fetch('reportes_api.php',{method:'POST',body:fd,headers:{'X-Requested-With':'XMLHttpRequest'}})
    .then(async function(r){
      var raw=await r.text();
      var data;
      try{ data=JSON.parse(String(raw||'').replace(/^\uFEFF/,'')); }
      catch(e){
        var clean=String(raw||'').replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim();
        throw new Error(clean ? clean.substring(0,500) : 'El servidor devolvió una respuesta no válida.');
      }
      if(!r.ok || !data.ok) throw new Error(data.error||'Error');
      return data;
    });
}
function note(t,ok){document.getElementById('msg').innerHTML='<div class="status '+(ok?'ok':'error')+'" style="display:block;margin-bottom:12px">'+t+'</div>'}
document.getElementById('scheduleForm').onsubmit=e=>{e.preventDefault();post(new FormData(e.target)).then(d=>{note(d.message,true);setTimeout(()=>location.reload(),500)}).catch(e=>note(e.message,false))};document.getElementById('settingsForm').onsubmit=e=>{e.preventDefault();post(new FormData(e.target)).then(d=>note(d.message,true)).catch(e=>note(e.message,false))};
function editSchedule(r){sid.value=r.ID;nombre.value=r.NOMBRE;destinatarios.value=r.DESTINATARIOS;cc.value=r.CC||'';cco.value=r.CCO||'';asunto.value=r.ASUNTO;cuerpo.value=r.CUERPO||'';frecuencia.value=r.FRECUENCIA;horarios.value=r.HORARIOS;zona_horaria.value=r.ZONA_HORARIA;activo.value=r.ACTIVO?'1':'0';document.querySelectorAll('[name="dias[]"]').forEach(x=>x.checked=String(r.DIAS_SEMANA||'').split(',').includes(x.value));var screens=String(r.PANTALLAS||r.TIPO_REPORTE||'dashboard').split(',');document.querySelectorAll('[name="pantallas[]"]').forEach(x=>x.checked=screens.includes(x.value));formTitle.textContent='Editar reporte';window.scrollTo({top:0,behavior:'smooth'})}function resetForm(){document.getElementById('scheduleForm').reset();sid.value='';formTitle.textContent='Nuevo reporte'}function sendNow(id){if(!confirm('¿Generar el PDF y enviar una prueba ahora?'))return;let f=new FormData();f.append('action','send_now');f.append('id',id);post(f).then(d=>{note(d.message,true);setTimeout(()=>location.reload(),800)}).catch(e=>note(e.message,false))}function removeSchedule(id){if(!confirm('¿Eliminar esta programación?'))return;let f=new FormData();f.append('action','delete_schedule');f.append('id',id);post(f).then(()=>location.reload()).catch(e=>note(e.message,false))}
</script></body></html>
